WITH exploded AS (SELECT id, customer_id, created_at, coupon_codes, pos, item.product_id, item.price, item.promo FROM carts LATERAL VIEW POSEXPLODE(items) x AS pos, item) SELECT *, LAG(price, 1) OVER (PARTITION BY customer_id, promo ORDER BY pos, id, pos) AS prev_price, FIRST_VALUE(pos) IGNORE NULLS OVER (PARTITION BY promo ORDER BY created_at, id, pos ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_pos FROM exploded;
